'use strict';

let base = {};
try { base = $('Set | Scheduler Constants | StateScheduler').first().json || {}; } catch {}
const clean = value => String(value ?? '').normalize('NFKC').trim();
const rows = $input.all().flatMap(item => {
  const value = item?.json?.body ?? item?.json ?? {};
  return Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : [value]);
});

return rows.filter(row => row && clean(row.session_id ?? row.sessionId) &&
  clean(row.job_id ?? row.jobId) && clean(row.lease_token ?? row.leaseToken) &&
  Number.isSafeInteger(Number(row.session_version ?? row.sessionVersion)) &&
  Number.isSafeInteger(Number(row.job_version ?? row.jobVersion)) &&
  ['clarified', 'fallback', 'expired_fallback'].includes(clean(row.resolution_mode ?? row.resolutionMode)) &&
  clean(row.principal_id ?? row.principalId) && clean(row.input_id ?? row.inputId) &&
  clean(row.content) && /^\d{4}-\d{2}-\d{2}$/.test(clean(row.local_date ?? row.localDate)) &&
  Number.isSafeInteger(Number(row.rule_set_version ?? row.ruleSetVersion)) &&
  Number.isSafeInteger(Number(row.rule_catalog_version ?? row.ruleCatalogVersion))
).map(row => ({ json: {
  ...base,
  ...row,
  stateClarificationFinalization: row,
  stateClarificationFinalizationContractVersion: 'chelsea_state_clarification_finalization_claim_v1'
} }));

'use strict';

const claim = $('Code | Normalize Clarification Finalization Claims | ClarificationFinalize').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const finalization = claim.stateClarificationFinalization || claim;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const session = body?.clarificationSession ?? body?.clarification_session;
const catalog = body?.ruleCatalog ?? body?.rule_catalog;
const expectedSessionId = clean(finalization.session_id ?? finalization.sessionId);
const expectedRuleSetCode = clean(finalization.rule_set_code ?? finalization.ruleSetCode);
const expectedRuleSetVersion = Number(finalization.rule_set_version ?? finalization.ruleSetVersion);
const expectedCatalogVersion = Number(finalization.rule_catalog_version ?? finalization.ruleCatalogVersion);
const expectedRuleCode = clean(finalization.rule_code ?? finalization.ruleCode);
const expectedResolutionMode = clean(finalization.resolution_mode ?? finalization.resolutionMode);
const ready = body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_analysis_context_v2' &&
  clean(body.principalId ?? body.principal_id) === clean(finalization.principal_id ?? finalization.principalId) &&
  Number(body.ruleCatalogVersion ?? body.rule_catalog_version) === expectedCatalogVersion &&
  catalog && typeof catalog === 'object' && !Array.isArray(catalog) &&
  clean(catalog.ruleSetCode ?? catalog.rule_set_code) === expectedRuleSetCode &&
  Number(catalog.ruleSetVersion ?? catalog.rule_set_version) === expectedRuleSetVersion &&
  Number(catalog.ruleCatalogVersion ?? catalog.rule_catalog_version) === expectedCatalogVersion &&
  session && typeof session === 'object' && !Array.isArray(session) &&
  clean(session.sessionId ?? session.session_id) === expectedSessionId &&
  clean(session.status) === 'finalizing' &&
  clean(session.ruleSetCode ?? session.rule_set_code) === expectedRuleSetCode &&
  Number(session.ruleSetVersion ?? session.rule_set_version) === expectedRuleSetVersion &&
  clean(session.ruleCode ?? session.rule_code) === expectedRuleCode &&
  clean(session.resolutionMode ?? session.resolution_mode) === expectedResolutionMode;

return [{ json: {
  ...claim,
  analysisContext: ready ? body : {},
  stateClarificationFinalizationContextReady: ready,
  stateClarificationFinalizationContextError: ready
    ? ''
    : String(body?.message || body?.error?.message || body?.hint || 'clarification_finalization_context_invalid').slice(0, 2000)
} }];

'use strict';

const input = $input.first()?.json || {};
const claim = input.stateClarificationFinalization || input;
const context = input.analysisContext && typeof input.analysisContext === 'object' ? input.analysisContext : {};
const clean = value => String(value ?? '').normalize('NFKC').trim();
const resolutionMode = clean(claim.resolution_mode ?? claim.resolutionMode);
const needsModel = resolutionMode === 'clarified';
const fallback = claim.neutral_fallback ?? claim.neutralFallback;
const session = context.clarificationSession ?? context.clarification_session ?? {};
const sessionAnswers = Array.isArray(session.answers) ? session.answers : [];
const relevantAnswers = sessionAnswers.filter(answer => {
  const status = clean(answer?.status);
  return !status || status === 'resolved';
});
const answerSegments = relevantAnswers.map(answer => clean(answer?.answerText ?? answer?.answer_text)).filter(Boolean);
const rawResolvedSlots = session.resolvedSlots ?? session.resolved_slots;
const resolvedSlots = rawResolvedSlots && typeof rawResolvedSlots === 'object' && !Array.isArray(rawResolvedSlots)
  ? rawResolvedSlots
  : {};
const sanitizedSession = { ...session, answers: relevantAnswers };
const sanitizedContext = needsModel ? {
  ...context,
  clarificationSession: sanitizedSession,
  ...(Object.prototype.hasOwnProperty.call(context, 'clarification_session')
    ? { clarification_session: sanitizedSession }
    : {})
} : context;
const stateJob = {
  job_id: clean(claim.job_id ?? claim.jobId),
  job_version: Number(claim.job_version ?? claim.jobVersion),
  lease_token: clean(claim.lease_token ?? claim.leaseToken),
  principal_id: clean(claim.principal_id ?? claim.principalId),
  input_id: clean(claim.input_id ?? claim.inputId),
  session_id: clean(claim.session_id ?? claim.sessionId),
  content: clean(claim.content),
  local_date: clean(claim.local_date ?? claim.localDate),
  context_json: claim.context_json ?? claim.contextJson ?? {},
  rule_set_code: clean(claim.rule_set_code ?? claim.ruleSetCode),
  rule_set_version: Number(claim.rule_set_version ?? claim.ruleSetVersion),
  rule_catalog_version: Number(claim.rule_catalog_version ?? claim.ruleCatalogVersion),
  analysis_mode: needsModel ? 'standard' : 'neutral_without_clarification',
  collectedClarificationAnswerSegments: answerSegments
};
const fallbackReady = !needsModel && fallback && typeof fallback === 'object' && !Array.isArray(fallback) &&
  fallback.analysisMode === 'neutral_without_clarification' && fallback.clarification?.needed === false;
const modelReady = needsModel && input.stateClarificationFinalizationContextReady === true &&
  clean(session.resolutionMode ?? session.resolution_mode) === 'clarified' &&
  answerSegments.length > 0 && Object.keys(resolvedSlots).length > 0;
const ready = fallbackReady || modelReady;

return [{ json: {
  ...input,
  stateJob,
  analysisContext: sanitizedContext,
  stateClarificationFinalizationNeedsModel: needsModel,
  stateClarificationFinalizationReady: ready,
  stateClarificationFinalizationError: ready
    ? ''
    : (needsModel ? 'clarified_finalization_context_incomplete' : 'stored_neutral_fallback_invalid'),
  stateAnalysisResult: fallbackReady ? fallback : null,
  stateAnalysisValid: fallbackReady,
  stateAnalysisModel: fallbackReady ? 'catalog-neutral-fallback' : '',
  stateAnalysisPromptVersion: fallbackReady ? 'chelsea_state_neutral_fallback_v1' : '',
  stateAnalysisRuleSetCode: clean(claim.rule_set_code ?? claim.ruleSetCode),
  stateAnalysisRuleSetVersion: Number(claim.rule_set_version ?? claim.ruleSetVersion),
  stateAnalysisRuleCatalogVersion: Number(claim.rule_catalog_version ?? claim.ruleCatalogVersion),
  stateApplyKey: `state_session_apply:${clean(claim.session_id ?? claim.sessionId)}`
} }];

'use strict';

const parsed = $input.first()?.json || {};
const original = parsed.stateAnalysisRequest;
if (!original || typeof original !== 'object') throw new Error('State analysis repair: original request is missing.');

const errors = Array.isArray(parsed.stateAnalysisErrors) ? parsed.stateAnalysisErrors.slice(0, 100) : ['unknown_validation_error'];
const invalidOutput = String(parsed.stateAnalysisRawText || '').slice(0, 30000);
const ruleCatalog = parsed.stateAnalysisRuleCatalog && typeof parsed.stateAnalysisRuleCatalog === 'object'
  ? parsed.stateAnalysisRuleCatalog
  : null;
if (!ruleCatalog) throw new Error('State analysis repair: active rule catalog is missing.');

const repairInstruction = [
  'Исправь предыдущий результат полностью. Верни новый полный JSON по той же strict schema, не patch.',
  'Устрани каждую ошибку валидатора и сохрани schemaVersion=chelsea_state_analysis_v2.',
  `Используй только этот active ruleCatalog: ${JSON.stringify(ruleCatalog)}.`,
  'Верхний результат обязан точно копировать ruleSetCode, ruleSetVersion и ruleCatalogVersion из active ruleCatalog.',
  'Не добавляй собственные связи event→sphere, polarity, impactScale, clarification или finance. Исполняй выбранное правило каталога.',
  'Каждый event обязан иметь активный ruleCode и точный ruleSetVersion. Каждый effect обязан точно копировать effectRuleCode, sphereCode и direction одного разрешённого allowedEffects.',
  'Соблюдай все диапазоны strength/confidence, allowedDurationDays, allowedImpactBases, requiredEffectGroups, polarityMode, allowedImpactScales и maxEffects.',
  'Finance разрешён только financePolicy выбранного правила; outcome/direction/evidencePattern должны совпасть с каталогом.',
  'Вопрос, его варианты и missingFields должны точно соответствовать одной clarificationPolicy.questions выбранного ruleCode.',
  'При clarification.needed=true neutralFallback обязателен. Он использует neutral_without_clarification, strength=1, confidence=0.60, neutralScale правила, пустые userScores/retractions, точно повторяет futurePlans верхнего результата и содержит clarification=false.',
  'При intake_enrichment основные mutation-массивы пусты, target/version null, а fallback содержит минимум одно событие выбранного ruleCode.',
  'При effect_resolution сохраняй target CAS и ruleCode target. Fallback не содержит supersede/retraction и не меняет неоднозначный target.',
  'При clarification.needed=false neutralFallback=null, все остальные nullable clarification-поля null, questionOptions/missingFields пусты.',
  'Буквальные evidence разрешены только из currentMessage.content или currentMessage.collectedClarificationAnswerSegments исходного запроса.',
  'Исправь временную привязку по currentMessage.temporalContext: today/вчера/явная дата задают occurredOn и startsOn завершённого события; обе даты совпадают и не позже latestMutableDate.',
  'Полностью удали планы и намерения из events/userScores/retractions и clarification: они не меняют баллы. Конкретный личный план с разрешимой датой сохрани только в futurePlans.',
  'Для futurePlans plannedFor не раньше anchorLocalDate; сегодня=today, завтра=tomorrow, послезавтра=dayAfterTomorrow, явная дата преобразуется точно. Без надёжной даты план не сохраняй и вопрос не задавай.',
  'futurePlan.planSemanticKey стабилен и не содержит дату/ID; evidenceText и temporalEvidenceText являются буквальными непрерывными фрагментами источника. Прогнозы и чужие действия не являются планами пользователя.',
  'temporalEvidenceText копируй буквальным непрерывным фрагментом источника, доказывающим дату и завершённость; не вырезай слова из будущего плана так, чтобы он выглядел свершившимся.',
  'currentMessage.clarificationSession.resolvedSlots и currentMessage.collectedClarificationAnswerSegments — разрешённые уточнённые данные; не задавай повторный вопрос по уже заполненному slotCode.',
  'При currentMessage.clarificationSession.status=finalizing и resolutionMode=clarified обязательно верни clarification.needed=false и не создавай новый цикл уточнений.',
  'Не переставляй слова, не исправляй регистр и не перефразируй evidence. Если короткий фрагмент не получается, используй один разрешённый источник целиком.',
  'dailySemanticKey должен быть стабильным и не дублировать точный или близкий ключ того же локального дня.',
  'Для sphere_default бери durationDays из ruleCatalog.sphereDefaults; durationEvidence=null.',
  'explicit_user_duration используй только с буквальным признаком продолжающегося/повторяющегося влияния; «сегодня» таким признаком не является.',
  `Ошибки: ${JSON.stringify(errors)}`,
  `Предыдущий результат: ${invalidOutput || '(пусто)'}`
].join('\n');

const request = {
  ...original,
  input: [
    ...(Array.isArray(original.input) ? original.input : []),
    { role: 'user', content: [{ type: 'input_text', text: repairInstruction }] }
  ]
};

return [{
  json: {
    ...parsed,
    stateAnalysisRequest: request,
    stateAnalysisRepairAttempted: true,
    stateAnalysisPromptVersion: 'chelsea_state_analysis_prompt_v2_2_future_plans_repair'
  }
}];

'use strict';

const parsed = $input.first()?.json || {};
const job = parsed.stateJob && typeof parsed.stateJob === 'object' ? parsed.stateJob : parsed;
const result = parsed.stateAnalysisResult;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const jobId = clean(job.job_id ?? job.jobId);
const leaseToken = clean(job.lease_token ?? job.leaseToken);
const jobVersion = Number(job.job_version ?? job.jobVersion);
const localDate = clean(job.local_date ?? job.localDate ?? parsed.asOfDate);
const ruleSetCode = clean(parsed.stateAnalysisRuleSetCode ?? job.rule_set_code ?? job.ruleSetCode);
const ruleSetVersion = Number(parsed.stateAnalysisRuleSetVersion ?? job.rule_set_version ?? job.ruleSetVersion);
const ruleCatalogVersion = Number(parsed.stateAnalysisRuleCatalogVersion ?? job.rule_catalog_version ?? job.ruleCatalogVersion);
const sessionId = clean(job.session_id ?? job.sessionId);
const applyKey = clean(parsed.stateApplyKey) || (sessionId
  ? `state_session_apply:${sessionId}`
  : `state_analysis_apply:${jobId}:v${jobVersion}:catalog${ruleCatalogVersion}`);
const futurePlans = Array.isArray(result?.futurePlans) ? result.futurePlans : null;
const ready = Boolean(jobId && leaseToken && Number.isSafeInteger(jobVersion) && localDate &&
  ruleSetCode && Number.isSafeInteger(ruleSetVersion) && Number.isSafeInteger(ruleCatalogVersion) &&
  result && typeof result === 'object' && !Array.isArray(result) && futurePlans);

return [{ json: {
  ...parsed,
  stateAnalysisApplyReady: ready,
  stateAnalysisApplyError: ready ? '' : 'analysis_apply_v3_input_incomplete',
  stateApplyKey: applyKey,
  stateRpcBody: {
    p_job_id: jobId,
    p_lease_token: leaseToken,
    p_expected_job_version: jobVersion,
    p_apply_key: applyKey,
    p_model_name: clean(parsed.stateAnalysisModel) || 'gpt-5.6-luna',
    p_prompt_version: clean(parsed.stateAnalysisPromptVersion) || 'chelsea_state_analysis_prompt_v2_2_future_plans',
    p_result: result,
    p_as_of_date: localDate,
    p_rule_set_code: ruleSetCode,
    p_rule_set_version: String(ruleSetVersion),
    p_rule_catalog_version: ruleCatalogVersion
  }
} }];

'use strict';

let source = {};
for (const nodeName of [
  'Code | Build Analysis Apply RPC | Analysis',
  'Code | Build Finalization Apply RPC | ClarificationFinalize'
]) {
  try {
    const candidate = $(nodeName).item.json || {};
    if (candidate.stateRpcBody?.p_job_id) { source = candidate; break; }
  } catch {}
}
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const expectedJobId = String(source.stateRpcBody?.p_job_id || '');
const futurePlans = Array.isArray(body?.futurePlans) ? body.futurePlans : null;
const contractVersion = String(body?.contractVersion || '');
const supportedContract = contractVersion === 'chelsea_state_apply_v3' ||
  contractVersion === 'chelsea_state_apply_v4';
const versionSpecificFieldsValid = contractVersion !== 'chelsea_state_apply_v4' ||
  typeof body?.eventCorrection === 'boolean';
const valid = body && typeof body === 'object' && !Array.isArray(body) &&
  supportedContract && versionSpecificFieldsValid &&
  String(body.jobId || '') === expectedJobId &&
  Boolean(body.analysisRunId) &&
  Number.isSafeInteger(Number(body.futurePlanCount)) &&
  Number(body.futurePlanCount) >= 0 && futurePlans;

return [{ json: {
  ...source,
  stateAnalysisApplyResult: body,
  stateAnalysisApplySucceeded: Boolean(valid),
  stateAnalysisApplyError: valid
    ? ''
    : String(body?.message || body?.error?.message || body?.hint || 'analysis_apply_receipt_failed').slice(0, 2000)
} }];

'use strict';

const input = $input.first()?.json || {};
const claim = input.stateClarificationFinalization || input;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const errors = [
  input.stateClarificationFinalizationContextError,
  input.stateClarificationFinalizationError,
  ...(Array.isArray(input.stateAnalysisErrors) ? input.stateAnalysisErrors : []),
  input.stateAnalysisApplyError,
  input.message,
  input.error?.message
].map(clean).filter(Boolean);
const errorText = errors.join('; ').slice(0, 2000) || 'Clarification finalization failed.';

return [{ json: {
  ...input,
  stateRpcBody: {
    p_session_id: clean(claim.session_id ?? claim.sessionId),
    p_lease_token: clean(claim.lease_token ?? claim.leaseToken),
    p_expected_session_version: Number(claim.session_version ?? claim.sessionVersion),
    p_error_code: (errors[0] || 'clarification_finalization_failed').slice(0, 120),
    p_error_text: errorText,
    p_retry_delay_minutes: 1
  }
} }];
